int sharedLineUnits(bool full){int n=0;auto require=[&](bool x){n++;if(!x)throw std::logic_error("shared line unit "+std::to_string(n));};const bool oldHint=kingHintEnabled;kingHintEnabled=true;
if(full){for(int row=0;row<10;row++)for(int mask=0;mask<512;mask++){OccupiedBits b;for(int i=0;i<9;i++)if(mask&(1<<i))b.toggle(row*9+i);require(rankOf(b,row)==mask);}for(int file=0;file<9;file++)for(int mask=0;mask<1024;mask++){OccupiedBits b;for(int i=0;i<10;i++)if(mask&(1<<i))b.toggle(i*9+file);require(fileOf(b,file)==mask);}for(int mask=0;mask<256;mask++){uint64_t spread=0;for(int i=0;i<8;i++)if(mask&(1<<i))spread|=uint64_t(1)<<(9*i);require(gatherDiagonal(spread)==mask);}}

if(full)for(int k=0;k<10;k++)for(int mask=0;mask<1024;mask++)for(int from=0;from<10;from++)if((mask&(1<<from))&&!nearRayRelevant(k,from,lineTable[k][mask].blockers)){require(lineTable[k][mask^(1<<from)].blockers==lineTable[k][mask].blockers);for(int to=0;to<10;to++)if(to!=from&&!nearRayRelevant(k,to,lineTable[k][mask].blockers)){const int changed=(mask^(1<<from))|(1<<to);require(lineTable[k][changed].blockers==lineTable[k][mask].blockers);}}

if(full)for(int axis=0;axis<2;axis++){const int length=axis?10:9;for(int k=0;k<length;k++)for(int mask=0;mask<(1<<length);mask++)for(int side:{0,1})for(int type:{R,C})for(bool hidden:{false,true}){Board b{};for(int i=0;i<length;i++)if(mask&(1<<i))b[axis?i*9+4:4*9+i]={((i+mask)&1)?side:side^1,P,P,false};const int f=axis?k*9+4:4*9+k;b[f]={side,hidden?N:type,type,hidden};OccupiedBits occupied;for(int i=0;i<90;i++)if(b[i].live())occupied.toggle(i);for(bool captures:{false,true}){auto actual=lineDestinations(b,occupied,f,captures,-1);std::vector<int> expected;for(int t:candidates(b,f,captures))if(pseudo(b,f,t))expected.push_back(t);require(expected==std::vector<int>(actual.begin(),actual.end()));}}}
uint32_t seed=0x39fa6721;auto rng=[&](){seed^=seed<<13;seed^=seed>>17;seed^=seed<<5;return seed;};for(int test=0;test<(full?2000:40);test++){Board b{};for(int i=0;i<90;i++)if(rng()%100<35)b[i]={int(rng()%2),1+int(rng()%6),int(rng()%7),bool(rng()%2)};b[72+int(rng()%18)]={0,K,K,false};b[int(rng()%18)]={1,K,K,false};State s=stateOf(b,{},test%2,test%2);for(int side:{0,1}){require(lineCheck(b,side,s.kings[side],s.occupied)==inCheck(b,side,s.kings[side]));for(bool captures:{false,true})for(bool first:{false,true}){std::vector<Move> actual,expected;lineLegalInto(b,s.occupied,side,captures,first,s.kings[side],actual);legalInto(b,side,captures,first,s.kings[side],expected);require(actual==expected);require(s.board==b);if(side==s.turn&&!actual.empty()){const Move m=actual[rng()%actual.size()];const auto occupied=s.occupied;const auto key=s.key();const Board board=s.board;const Undo u=push(s,m);auditOccupied(s);pop(s,m,u);require(s.board==board&&s.occupied==occupied&&s.key()==key);}}}}kingHintEnabled=oldHint;return n;}
